def build_lcf(n, shifts):
    adj = {i:set() for i in range(n)}
    for i in range(n):
        adj[i].add((i+1)%n)
        adj[(i+1)%n].add(i)
    for i in range(n):
        s = shifts[i % len(shifts)]
        j = (i + s) % n
        adj[i].add(j); adj[j].add(i)
    return adj

